def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, op_last = history[-1]
    if op_last == 'D':
        opp_def = sum(1 for _, o in history if o == 'D')
        my_def = sum(1 for m, _ in history if m == 'D')
        if opp_def <= max(1, n // 10):
            return 'C'
        if my_last == 'D' and opp_def <= n // 2:
            return 'C'
        return 'D'
    else:
        opp_def = sum(1 for _, o in history if o == 'D')
        my_def = sum(1 for m, _ in history if m == 'D')

        # Probing to exploit never-defecting opponents
        if opp_def == 0:
            if my_def == 0 and n in (20, 40, 60, 80):
                return 'D'
            if my_def == 1 and n in (40, 60, 80):
                return 'D'
            if my_def >= 2:
                return 'D'

        # Original exploit pattern check
        if n >= 2:
            recent_my = [m for m, _ in history[-3:]]
            recent_op = [o for _, o in history[-3:]]
            if all(m == 'D' for m in recent_my) and all(o == 'C' for o in recent_op):
                return 'D'

        return 'C'
